-- Public bearer-code tracking: exact random 20-hex parcel code generated by OS.
-- Only fixed operational states and timestamps leave the private schema.
-- No anonymous table grants, identifiers, addresses, identity or proof files.
create schema if not exists tracking_private;
revoke all on schema tracking_private from public;
create function tracking_private.lookup_public_tracking(p_code text)
returns jsonb language plpgsql stable security definer set search_path=''
as $$
declare
  v_code text; v_shipment text; v_org text; v_created timestamptz;
begin
  if p_code is null or length(p_code)>64 then return null; end if;
  v_code := upper(btrim(p_code));
  if v_code !~ '^B-[0-9A-F]{20}$' then return null; end if;
  select s.id,s.org_id,s.created_at into v_shipment,v_org,v_created
    from nexora.parcels p join nexora.shipments s on s.id=p.shipment_id and s.org_id=p.org_id
    where p.code=v_code;
  if v_shipment is null then return null; end if;
  return jsonb_build_object('code',v_code,'createdAt',v_created,
    'counts',(select jsonb_object_agg(state,amount) from
      (select p.state,count(*) as amount from nexora.parcels p
       where p.shipment_id=v_shipment and p.org_id=v_org group by p.state) c),
    'events',coalesce((select jsonb_agg(jsonb_build_object('action',e.action,'at',e.created_at) order by e.created_at)
      from (select distinct ce.action,ce.created_at from nexora.custody_events ce
        join nexora.parcels p on p.id=ce.parcel_id and p.org_id=ce.org_id
        where p.shipment_id=v_shipment and p.org_id=v_org
          and ce.action in ('RECEIVED','LOADED','DISPATCHED','DIRECT_PICKUP','DELIVERED','DELIVERY_FAILED','RETURN_RECEIVED','RETURNED_TO_SENDER')
        order by ce.created_at desc limit 50) e),'[]'::jsonb));
end;
$$;
revoke all on function tracking_private.lookup_public_tracking(text) from public,anon,authenticated;
grant usage on schema tracking_private to anon,authenticated;
grant execute on function tracking_private.lookup_public_tracking(text) to anon,authenticated;
create function public.track_order(p_code text)
returns jsonb language sql stable security invoker set search_path=''
as $$ select tracking_private.lookup_public_tracking(p_code); $$;
revoke all on function public.track_order(text) from public,anon,authenticated;
grant execute on function public.track_order(text) to anon,authenticated;
comment on function tracking_private.lookup_public_tracking(text) is 'Intentional public bearer-code lookup; exact OS random code required. Returns status counts and fixed milestone timestamps only.';
